// ═══════════════════════════════════════════════════════════
// 🧠 ANÁLISE DE RISCO E QUALIFICAÇÃO
// ═══════════════════════════════════════════════════════════

const lead = $input.first().json;
const ipData = $node['1️⃣ Validar IP (Geolocalização)'].json;
const emailData = $node['2️⃣ Validar Email (Hunter.io)'].json;
const googleResults = $node['3️⃣ Google Search (Nome + Empresa)'].json;
const linkedinData = $node['4️⃣ LinkedIn Search (Proxycurl)'].json;
const companyData = $node['5️⃣ Enriquecer Empresa (Clearbit)'].json;

let riskScore = 0; // 0-100 (quanto maior, mais suspeito)
let qualityScore = 100; // 0-100 (quanto maior, melhor)
let flags = [];
let insights = [];

// ═══════════════════════════════════════════════════════════
// 🚩 VERIFICAÇÕES DE RISCO
// ═══════════════════════════════════════════════════════════

// 1️⃣ IP SUSPEITO
if (ipData.proxy || ipData.hosting) {
  riskScore += 30;
  flags.push('🚨 IP via proxy/VPN/hosting');
}

if (ipData.threat_level === 'high') {
  riskScore += 50;
  flags.push('⛔ IP em lista de ameaças');
}

// Verificar se IP condiz com cidade informada
if (lead.city && ipData.city && lead.city.toLowerCase() !== ipData.city.toLowerCase()) {
  riskScore += 20;
  flags.push(`⚠️ Cidade informada (${lead.city}) ≠ IP real (${ipData.city})`);
}

// 2️⃣ EMAIL SUSPEITO
if (emailData.result === 'undeliverable') {
  riskScore += 100; // Email inválido = descarte imediato
  flags.push('❌ Email inválido/inexistente');
}

if (emailData.disposable) {
  riskScore += 60;
  flags.push('🗑️ Email descartável (temp mail)');
}

if (emailData.role) {
  riskScore += 10;
  insights.push('📧 Email genérico (info@, contato@, etc)');
}

// 3️⃣ GOOGLE SEARCH - NADA ENCONTRADO
if (!googleResults.items || googleResults.items.length === 0) {
  riskScore += 25;
  flags.push('🔍 Nome/empresa não encontrados no Google');
  qualityScore -= 30;
}

// 4️⃣ LINKEDIN - PERFIL FALSO/INEXISTENTE
if (!linkedinData.results || linkedinData.results.length === 0) {
  riskScore += 20;
  flags.push('👤 Não encontrado no LinkedIn');
  qualityScore -= 20;
} else {
  const profile = linkedinData.results[0];

  // Perfil recente = suspeito
  if (profile.profile_created_recently) {
    riskScore += 15;
    flags.push('🆕 Perfil LinkedIn criado recentemente');
  }

  // Sem conexões = suspeito
  if (profile.connections < 10) {
    riskScore += 10;
    flags.push('📉 Perfil com poucas conexões (<10)');
  }

  // Cargo condiz?
  insights.push(`💼 Cargo: ${profile.headline}`);
  insights.push(`🏢 Empresa: ${profile.company}`);
}

// 5️⃣ EMPRESA - CONCORRENTE?
const competitorDomains = [
  'studioazul.com.br',
  'outroproducao.com',
  'concorrente.com'
  // Adicione seus concorrentes aqui
];

const emailDomain = lead.email.split('@')[1];
if (competitorDomains.includes(emailDomain)) {
  riskScore += 80;
  flags.push('⚔️ ALERTA: Concorrente identificado!');
}

// Empresa legítima?
if (companyData.error) {
  riskScore += 15;
  flags.push('🏭 Empresa não encontrada no Clearbit');
  qualityScore -= 20;
} else {
  insights.push(`🏢 Empresa: ${companyData.name} (${companyData.domain})`);
  insights.push(`👥 Funcionários: ${companyData.metrics.employees || 'N/A'}`);
  insights.push(`💰 Receita: ${companyData.metrics.estimatedAnnualRevenue || 'N/A'}`);

  // Empresa grande = lead qualificado
  if (companyData.metrics.employees > 50) {
    qualityScore += 20;
  }
}

// 6️⃣ COMPORTAMENTO NO SITE
if (lead.timeOnSite < 30) {
  riskScore += 10;
  flags.push('⏱️ Tempo no site muito curto (<30s)');
}

if (lead.pagesVisited?.length === 1) {
  riskScore += 5;
  flags.push('📄 Visitou apenas 1 página');
}

// ═══════════════════════════════════════════════════════════
// 🎯 DECISÃO FINAL
// ═══════════════════════════════════════════════════════════

let decision = 'SEND'; // SEND | CAUTION | REJECT
let action = '';

if (riskScore >= 80) {
  decision = 'REJECT';
  action = '❌ NÃO ENVIAR EMAIL - Lead muito suspeito';
} else if (riskScore >= 40) {
  decision = 'CAUTION';
  action = '⚠️ ENVIAR EMAIL GENÉRICO - Lead suspeito, monitorar';
} else {
  decision = 'SEND';
  action = '✅ ENVIAR EMAIL PERSONALIZADO - Lead legítimo';
}

// ═══════════════════════════════════════════════════════════
// 📊 OUTPUT
// ═══════════════════════════════════════════════════════════

return {
  json: {
    // Dados originais
    lead: lead,

    // Dados enriquecidos
    enrichment: {
      realCity: ipData.city,
      realCountry: ipData.country_name,
      emailValid: emailData.result === 'deliverable',
      emailCorporate: !emailData.disposable && !emailData.free,
      linkedinProfile: linkedinData.results?.[0]?.public_identifier || null,
      companyName: companyData.name || lead.company,
      companySize: companyData.metrics?.employees || null
    },

    // Análise de risco
    analysis: {
      riskScore: riskScore,
      qualityScore: qualityScore,
      decision: decision,
      action: action,
      flags: flags,
      insights: insights
    }
  }
};
